"""Golden matches: any change to generated bytes must be deliberate (design section 12.6).

To accept an intended change: `uv run pundit generate --scenario S --seed N --update-golden`,
review the diff of the *.summary.json file, and commit it together with the code.
"""

import json

import pytest

from pundit.cli import GOLDEN_DIR
from pundit.engine.generator import generate
from pundit.engine.io import match_hash, match_summary

GOLDEN = [("dominant_loser", 42), ("comeback_var", 7)]


@pytest.mark.parametrize(("scenario", "seed"), GOLDEN)
def test_golden_hash(scenario: str, seed: int) -> None:
    expected = (GOLDEN_DIR / f"{scenario}-{seed}.sha256").read_text(encoding="utf-8").strip()
    assert match_hash(generate(scenario, seed).events) == expected


@pytest.mark.parametrize(("scenario", "seed"), GOLDEN)
def test_golden_summary(scenario: str, seed: int) -> None:
    path = GOLDEN_DIR / f"{scenario}-{seed}.summary.json"
    expected = json.loads(path.read_text(encoding="utf-8"))
    assert match_summary(generate(scenario, seed)) == expected
